import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import useAuth from '../../hooks/useAuth';

const LOGO = "data:image/png;base64,";

const LoginPage: React.FC = () => {
    const { login, isAuthenticated } = useAuth();
    const navigate = useNavigate();

    const [identifier, setIdentifier] = useState('');
    const [password,   setPassword]   = useState('');
    const [showPwd,    setShowPwd]    = useState(false);
    const [loading,    setLoading]    = useState(false);
    const [error,      setError]      = useState<string | null>(null);

    useEffect(() => {
        if (isAuthenticated) navigate('/dashboard', { replace: true });
    }, [isAuthenticated, navigate]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!identifier.trim() || !password.trim()) {
            setError('Veuillez remplir tous les champs.'); return;
        }
        setLoading(true); setError(null);
        try {
            await login({ email: identifier.trim(), password });
        } catch {
            setError('Identifiant ou mot de passe incorrect.');
        } finally { setLoading(false); }
    };

    return (
        <div style={{
            minHeight: '100vh', display: 'flex',
            alignItems: 'center', justifyContent: 'center',
            background: 'linear-gradient(135deg, #F0F4F8 0%, #E8EEF6 100%)',
        }}>
            <div style={{
                display: 'flex', width: '100%', maxWidth: 900,
                borderRadius: 24, overflow: 'hidden',
                boxShadow: '0 25px 60px rgba(0,0,0,0.18)',
            }}>

                {/* ── Panneau gauche ── */}
                <div style={{
                    flex: '0 0 360px',
                    background: 'linear-gradient(160deg, #1A3A6B 0%, #2A5298 55%, #1565C0 100%)',
                    padding: '52px 40px', display: 'flex',
                    flexDirection: 'column', justifyContent: 'space-between',
                    color: '#fff', position: 'relative' as const, overflow: 'hidden',
                }}>
                    <div style={{
                        position: 'absolute' as const, top: -60, right: -60,
                        width: 200, height: 200, borderRadius: '50%',
                        background: 'rgba(255,255,255,0.04)',
                    }} />
                    <div style={{
                        position: 'absolute' as const, bottom: -80, left: -40,
                        width: 250, height: 250, borderRadius: '50%',
                        background: 'rgba(255,255,255,0.03)',
                    }} />

                    <div style={{ position: 'relative' as const }}>
                        {/* Logo dans cercle blanc */}
                        <div style={{
                            width: 110, height: 110, borderRadius: '50%',
                            background: '#fff', display: 'flex',
                            alignItems: 'center', justifyContent: 'center',
                            marginBottom: 24, boxShadow: '0 8px 24px rgba(0,0,0,0.2)',
                            padding: 10,
                        }}>
                            <img src={LOGO} alt="CATUSNIS"
                                style={{ width: 88, height: 88, objectFit: 'contain' }} />
                        </div>

                        <h2 style={{
                            fontSize: 26, fontWeight: 800,
                            margin: '0 0 4px', color: '#fff', letterSpacing: 1,
                        }}>CATUSNIS</h2>
                        <p style={{
                            fontSize: 12, color: 'rgba(255,255,255,0.6)',
                            margin: '0 0 32px', textTransform: 'uppercase' as const, letterSpacing: 2,
                        }}>Côte d&apos;Ivoire</p>
                        <p style={{
                            fontSize: 13, color: 'rgba(255,255,255,0.75)',
                            margin: '0 0 32px', lineHeight: 1.6,
                        }}>
                            Système de gestion des équipements de santé —
                            Traçabilité, déploiements et interventions.
                        </p>

                        {[
                            { icon: '🏥', text: 'Gestion des équipements médicaux'  },
                            { icon: '📦', text: 'Suivi des déploiements & livraisons' },
                            { icon: '🔧', text: 'Interventions techniques & maintenance' },
                            { icon: '🔒', text: 'Accès sécurisé par rôle'           },
                        ].map((f, i) => (
                            <div key={i} style={{
                                display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14,
                            }}>
                                <span style={{
                                    width: 34, height: 34, borderRadius: 8,
                                    background: 'rgba(255,255,255,0.12)',
                                    display: 'flex', alignItems: 'center',
                                    justifyContent: 'center', fontSize: 16, flexShrink: 0,
                                }}>{f.icon}</span>
                                <span style={{ fontSize: 13, color: 'rgba(255,255,255,0.85)' }}>
                                    {f.text}
                                </span>
                            </div>
                        ))}
                    </div>

                    <p style={{
                        fontSize: 10, color: 'rgba(255,255,255,0.35)',
                        margin: 0, position: 'relative' as const,
                    }}>
                        &copy; {new Date().getFullYear()} CATUSNIS &middot; v2.0
                    </p>
                </div>

                {/* ── Panneau droit ── */}
                <div style={{
                    flex: 1, background: '#fff', padding: '60px 52px',
                    display: 'flex', flexDirection: 'column', justifyContent: 'center',
                }}>
                    <div style={{ textAlign: 'center' as const, marginBottom: 40 }}>
                        <h3 style={{
                            fontSize: 28, fontWeight: 700, color: '#1A3A6B', margin: '0 0 6px',
                        }}>Bienvenue</h3>
                        <p style={{ fontSize: 14, color: '#F59E0B', margin: 0, fontWeight: 600 }}>
                            Connectez-vous à votre espace
                        </p>
                    </div>

                    <form onSubmit={handleSubmit}>
                        {error && (
                            <div style={{
                                background: '#FEF2F2', border: '1px solid #FECACA',
                                borderRadius: 10, padding: '10px 14px', marginBottom: 20,
                                color: '#DC2626', fontSize: 13,
                                display: 'flex', alignItems: 'center', gap: 8,
                            }}>
                                <i className="bi bi-exclamation-circle" />{error}
                            </div>
                        )}

                        {/* Identifiant */}
                        <div style={{ position: 'relative' as const, marginBottom: 16 }}>
                            <span style={{
                                position: 'absolute' as const, left: 14, top: '50%',
                                transform: 'translateY(-50%)', color: '#9CA3AF', fontSize: 17,
                            }}>
                                <i className="bi bi-person" />
                            </span>
                            <input type="text" placeholder="Identifiant"
                                value={identifier} onChange={e => setIdentifier(e.target.value)}
                                style={{
                                    width: '100%', padding: '14px 16px 14px 44px',
                                    border: '1.5px solid #E5E7EB', borderRadius: 12,
                                    fontSize: 14, outline: 'none', boxSizing: 'border-box' as const,
                                    color: '#111827', background: '#FAFAFA',
                                    transition: 'border-color .2s, box-shadow .2s',
                                }}
                                onFocus={e => {
                                    e.target.style.borderColor = '#2A5298';
                                    e.target.style.boxShadow  = '0 0 0 3px rgba(42,82,152,0.08)';
                                }}
                                onBlur={e => {
                                    e.target.style.borderColor = '#E5E7EB';
                                    e.target.style.boxShadow  = 'none';
                                }}
                            />
                        </div>

                        {/* Mot de passe */}
                        <div style={{ position: 'relative' as const, marginBottom: 32 }}>
                            <span style={{
                                position: 'absolute' as const, left: 14, top: '50%',
                                transform: 'translateY(-50%)', color: '#9CA3AF', fontSize: 17,
                            }}>
                                <i className="bi bi-lock" />
                            </span>
                            <input type={showPwd ? 'text' : 'password'} placeholder="Mot de passe"
                                value={password} onChange={e => setPassword(e.target.value)}
                                style={{
                                    width: '100%', padding: '14px 46px 14px 44px',
                                    border: '1.5px solid #E5E7EB', borderRadius: 12,
                                    fontSize: 14, outline: 'none', boxSizing: 'border-box' as const,
                                    color: '#111827', background: '#FAFAFA',
                                    transition: 'border-color .2s, box-shadow .2s',
                                }}
                                onFocus={e => {
                                    e.target.style.borderColor = '#2A5298';
                                    e.target.style.boxShadow  = '0 0 0 3px rgba(42,82,152,0.08)';
                                }}
                                onBlur={e => {
                                    e.target.style.borderColor = '#E5E7EB';
                                    e.target.style.boxShadow  = 'none';
                                }}
                            />
                            <button type="button" onClick={() => setShowPwd(s => !s)}
                                style={{
                                    position: 'absolute' as const, right: 14, top: '50%',
                                    transform: 'translateY(-50%)',
                                    background: 'none', border: 'none', cursor: 'pointer',
                                    color: '#9CA3AF', fontSize: 17, padding: 0,
                                }}>
                                <i className={`bi bi-eye${showPwd ? '-slash' : ''}`} />
                            </button>
                        </div>

                        {/* Bouton connexion */}
                        <button type="submit" disabled={loading}
                            style={{
                                width: '100%', padding: '15px',
                                background: loading
                                    ? '#9CA3AF'
                                    : 'linear-gradient(135deg, #1A3A6B, #2A5298)',
                                color: '#fff', border: 'none', borderRadius: 12,
                                fontSize: 15, fontWeight: 700,
                                cursor: loading ? 'not-allowed' : 'pointer',
                                display: 'flex', alignItems: 'center',
                                justifyContent: 'center', gap: 10,
                                transition: 'opacity .2s',
                                boxShadow: loading ? 'none' : '0 4px 14px rgba(26,58,107,0.35)',
                                letterSpacing: 0.5,
                            }}
                            onMouseEnter={e => { if (!loading) e.currentTarget.style.opacity = '0.9'; }}
                            onMouseLeave={e => { if (!loading) e.currentTarget.style.opacity = '1';   }}>
                            {loading
                                ? <><span className="spinner-border spinner-border-sm" /> Connexion...</>
                                : <><i className="bi bi-box-arrow-in-right" /> Se connecter</>}
                        </button>
                    </form>

                    <p style={{ textAlign: 'center' as const, fontSize: 11, color: '#9CA3AF', marginTop: 28 }}>
                        En vous connectant, vous acceptez nos{' '}
                        <span style={{ color: '#2A5298', cursor: 'pointer' }}>CGU</span>
                        {' '}et notre{' '}
                        <span style={{ color: '#2A5298', cursor: 'pointer' }}>Politique de confidentialité</span>.
                    </p>
                </div>

            </div>
        </div>
    );
};

export default LoginPage;